async def act(page):
    """Filter the Sales > Orders grid for cancelled orders and print the
    Purchased On / Created date of the most recent cancelled order (first
    matching row after applying the filter).

    Prints exactly one line: the date string (or an empty string if not
    found). This function continues from the current page state.
    """
    # small pause for any transient UI overlays to stabilize
    await page.wait_for_timeout(300)

    # Helper to get normalized inner text (NBSP -> space) from a locator
    async def _text_or_empty(locator):
        try:
            raw = await locator.inner_text()
        except Exception:
            raw = ""
        return (raw or "").replace("\u00A0", " ").strip()

    # 1) Find a combobox that contains a cancel/canceled/cancelled option and select it.
    combos = page.get_by_role("combobox")
    try:
        combo_count = await combos.count()
    except Exception:
        combo_count = 0

    selected_label = None
    for i in range(combo_count):
        combo = combos.nth(i)
        try:
            options = await combo.evaluate(
                "(el) => Array.from(el.options).map(o => ({label: (o.textContent||'').trim(), value: (o.value||'').trim()}))"
            )
        except Exception:
            continue

        if not options:
            continue

        # Prefer exact 'Canceled' or 'Cancelled' label, otherwise first containing 'cancel'
        chosen = None
        for opt in options:
            lbl = (opt.get('label') or '').strip()
            if lbl.lower() in ('canceled', 'cancelled'):
                chosen = lbl
                break
        if chosen is None:
            for opt in options:
                lbl = (opt.get('label') or '')
                if 'cancel' in lbl.lower():
                    chosen = lbl
                    break

        if not chosen:
            continue

        # Try selecting by exact visible label first, narrow fallback to value
        try:
            await combo.select_option(label=chosen)
            selected_label = chosen
            break
        except Exception:
            try:
                # find matching option value for same label
                match_value = None
                for opt in options:
                    if (opt.get('label') or '') == chosen and (opt.get('value') or '') != '':
                        match_value = opt.get('value')
                        break
                if match_value:
                    await combo.select_option(value=match_value)
                    selected_label = chosen
                    break
            except Exception:
                continue

    # 2) Apply the filter by clicking the Search button that belongs to the "Reset Filter Search" cell
    # Use full get_by_role path to avoid ambiguity.
    try:
        reset_cell = page.get_by_role("cell", name="Reset Filter Search")
        if await reset_cell.count() > 0:
            search_btn = reset_cell.nth(0).get_by_role("button", name="Search")
            if await search_btn.count() > 0:
                await search_btn.nth(0).click()
            else:
                # fallback: top-level Search button
                top_search = page.get_by_role("button", name="Search")
                if await top_search.count() > 0:
                    await top_search.nth(0).click()
                else:
                    # allow auto-apply time
                    await page.wait_for_timeout(700)
        else:
            top_search = page.get_by_role("button", name="Search")
            if await top_search.count() > 0:
                await top_search.nth(0).click()
            else:
                await page.wait_for_timeout(700)
    except Exception:
        # If clicking fails, wait for auto-apply
        await page.wait_for_timeout(800)

    # Give the grid time to refresh after applying the filter
    await page.wait_for_timeout(900)

    # 3) Locate the table that contains the Orders header (look for a table with a 'Purchased On' cell)
    tables = page.get_by_role("table")
    try:
        tcount = await tables.count()
    except Exception:
        tcount = 0

    target_table = None
    for ti in range(tcount):
        tbl = tables.nth(ti)
        try:
            if await tbl.get_by_role("cell", name="Purchased On").count() > 0:
                target_table = tbl
                break
        except Exception:
            continue

    if target_table is None:
        # nothing to read
        print("")
        return

    # 4) Inspect rows to find header row and column indices for Purchased On and Status
    try:
        rows = target_table.get_by_role("row")
        rcount = await rows.count()
    except Exception:
        print("")
        return

    header_row_index = None
    purchased_idx = None
    status_idx = None

    for ri in range(rcount):
        row = rows.nth(ri)
        try:
            # Prefer columnheader elements for header row, fallback to cell
            header_cells = row.get_by_role("columnheader")
            if await header_cells.count() == 0:
                header_cells = row.get_by_role("cell")
            hcount = await header_cells.count()
            if hcount == 0:
                continue

            headers = [await _text_or_empty(header_cells.nth(ci)) for ci in range(hcount)]
            # detect header row by presence of 'Purchased On' or 'Order #'
            if not any(('purchased on' in (h or '').lower()) or ('order #' in (h or '').lower()) for h in headers):
                continue

            header_row_index = ri
            for idx, h in enumerate(headers):
                low = (h or '').lower()
                if purchased_idx is None and (('purchased on' in low) or ('purchased' in low) or ('created' in low) or ('order date' in low) or (low == 'date') or ('date' in low)):
                    purchased_idx = idx
                if status_idx is None and 'status' in low:
                    status_idx = idx
            break
        except Exception:
            continue

    if purchased_idx is None:
        # can't find purchased column
        print("")
        return

    # 5) Iterate data rows after header and find first row whose status indicates cancel
    start = (header_row_index + 1) if header_row_index is not None else 0
    for dri in range(start, rcount):
        row = rows.nth(dri)
        try:
            data_cells = row.get_by_role('cell')
            dcount = await data_cells.count()
            if dcount == 0:
                # no data cells
                continue

            cell_texts = [await _text_or_empty(data_cells.nth(ci)) for ci in range(dcount)]

            # Determine whether this row is cancelled
            is_cancel = False
            if status_idx is not None and status_idx < len(cell_texts):
                if 'cancel' in (cell_texts[status_idx] or '').lower():
                    is_cancel = True
            else:
                for t in cell_texts:
                    if 'cancel' in (t or '').lower():
                        is_cancel = True
                        break

            if is_cancel:
                # Extract purchased/created value
                val = ''
                if purchased_idx < len(cell_texts):
                    val = cell_texts[purchased_idx]
                else:
                    # fallback: first date-like cell
                    for t in cell_texts:
                        if t and any(ch.isdigit() for ch in t):
                            val = t
                            break
                print(val or "")
                return
        except Exception:
            continue

    # If no cancelled rows found, print empty string deterministically
    print("")

